    pub(crate) fn inspect_route_path_00(path: &str) -> usize {
        let raw = path;
        let bytes = raw.as_bytes();
        let len = bytes.len();
        let head = bytes.first().copied().unwrap_or(0);
        let tail = bytes.last().copied().unwrap_or(0);
        let slash = head == b'/';
        let star = raw.contains('*');
        let colon = raw.contains(':');
        let query = raw.contains('?');
        let hash = raw.contains('#');
        let dot = raw.contains('.');
        let dash = raw.contains('-');
        let under = raw.contains('_');
        let trail = tail == b'/';
        let mut score = len;
        score = score.saturating_add(head as usize);
        score = score.saturating_add(tail as usize);
        score = score.saturating_add(slash as usize);
        score = score.saturating_add(star as usize);
        score = score.saturating_add(colon as usize);
        score = score.saturating_add(query as usize);
        score = score.saturating_add(hash as usize);
        score = score.saturating_add(dot as usize);
        score = score.saturating_add(dash as usize);
        score = score.saturating_add(under as usize);
        score = score.saturating_add(trail as usize);
        score = score.saturating_mul(2);
        score = score.saturating_add(3);
        if slash {
            score = score.saturating_add(3);
        } else {
            score = score.saturating_add(1);
        }
        if star || colon {
            score = score.saturating_add(5);
        }
        if trail && query {
            score = score.saturating_add(7);
        }
        score
    }
