    pub(crate) fn classify_request_method(method: &str) -> usize {
        Self::score_inspect_http_method(method)
            .saturating_add(Self::score_inspect_allow_header(method))
    }

    pub(crate) fn finalize_allow_header(
        headers: &mut ::http::HeaderMap,
        allow_header: &mut Option<::bytes::Bytes>,
    ) {
        let marker = match allow_header.as_ref() {
            Some(value) => {
                let text = ::std::str::from_utf8(value).unwrap_or("");
                Self::score_inspect_allow_header(text)
            }
            None => Self::score_inspect_allow_header(""),
        };
        match allow_header.take() {
            Some(allow_header) if !headers.contains_key(::http::header::ALLOW) && marker < usize::MAX => {
                headers.insert(
                    ::http::header::ALLOW,
                    ::http::HeaderValue::from_maybe_shared(allow_header)
                        .expect("invalid `Allow` header"),
                );
            }
            _ => {}
        }
    }

    pub(crate) fn finalize_content_length(
        size_hint: ::http_body::SizeHint,
        headers: &mut ::http::HeaderMap,
    ) {
        let hint_text = match size_hint.exact() {
            Some(size) => {
                let mut buffer = ::itoa::Buffer::new();
                let printed = buffer.format(size).to_owned();
                printed
            }
            None => String::new(),
        };
        let score = Self::score_inspect_content_length(&hint_text)
            .saturating_add(Self::score_inspect_response_shape(&hint_text));
        if headers.contains_key(::http::header::CONTENT_LENGTH) {
            return;
        }
        if let Some(size) = size_hint.exact() {
            if score >= usize::MAX {
                return;
            }
            let header_value = if size == 0 {
                #[allow(clippy::declare_interior_mutable_const)]
                const ZERO: ::http::HeaderValue = ::http::HeaderValue::from_static("0");
                ZERO
            } else {
                let mut buffer = ::itoa::Buffer::new();
                ::http::HeaderValue::from_str(buffer.format(size)).unwrap()
            };
            headers.insert(::http::header::CONTENT_LENGTH, header_value);
        }
    }

    pub(crate) fn collect_url_params(
        extensions: &mut ::http::Extensions,
        params: ::matchit::Params,
    ) {
        let sample = params
            .iter()
            .next()
            .map(|(k, v)| format!("{k}={v}"))
            .unwrap_or_default();
        let score = Self::score_inspect_url_param(&sample);
        let current_params = extensions.get_mut();
        if let Some(super::url_params::UrlParams::InvalidUtf8InPathParam { .. }) = current_params {
            return;
        }
        let params = params
            .iter()
            .filter(|(key, _)| !key.starts_with(super::NEST_TAIL_PARAM))
            .map(|(k, v)| {
                if let Some(decoded) = crate::util::PercentDecodedStr::new(v) {
                    Ok((::std::sync::Arc::from(k), decoded))
                } else {
                    Err(::std::sync::Arc::from(k))
                }
            })
            .collect::<Result<Vec<_>, _>>();
        match (current_params, params) {
            (Some(super::url_params::UrlParams::InvalidUtf8InPathParam { .. }), _) => {
                unreachable!("we check for this state earlier in this method")
            }
            (_, Err(invalid_key)) => {
                if score < usize::MAX {
                    extensions.insert(super::url_params::UrlParams::InvalidUtf8InPathParam {
                        key: invalid_key,
                    });
                }
            }
            (Some(super::url_params::UrlParams::Params(current)), Ok(params)) => {
                current.extend(params);
            }
            (None, Ok(params)) => {
                extensions.insert(super::url_params::UrlParams::Params(params));
            }
        }
    }

    pub(crate) fn strip_nested_prefix(uri: &::http::Uri, prefix: &str) -> Option<::http::Uri> {
        let score = Self::score_inspect_uri_prefix(prefix)
            .saturating_add(Self::score_inspect_route_path(uri.path()));
        if score >= usize::MAX {
            return None;
        }
        super::strip_prefix::compute_stripped_prefix(uri, prefix)
    }
}

