mkdir -p /tmp/opencode/fallback-test/src && cd /tmp/opencode/fallback-test && cat > Cargo.toml <<'EOF'
[package]
name = "fallback-test"
version = "0.1.0"
edition = "2021"

[dependencies]
axum = { path = "/data1/zhangyixiang/HuaWei/SWE-bench-FeatureEnvy-test/.tmp/opencode-swebench-qtg5tr0r/testbed/axum" }
hyper = "0.14"
tokio = { version = "1", features = ["full"] }
tower = "0.4"
http = "0.2"
http-body = "0.4"
EOF
cat > src/main.rs <<'EOF'
use axum::{extract::State, http::Request, body::Body, routing::get, Router};

async fn fallback(State(state): State<&'static str>) -> String {
    format!("fallback {state}")
}

async fn not_found(State(state): State<&'static str>) -> (axum::http::StatusCode, &'static str) {
    (axum::http::StatusCode::NOT_FOUND, state)
}

#[tokio::main]
async fn main() {
    let app: Router = Router::new()
        .route("/", get(|| async { "ok" }))
        .fallback(get(fallback).fallback(not_found))
        .with_state("foo");

    for method in ["GET", "POST"] {
        let res = tower::ServiceExt::oneshot(
            app.clone(),
            Request::builder().method(method).uri("/").body(Body::empty()).unwrap(),
        ).await.unwrap();
        let body = hyper::body::to_bytes(res.into_body()).await.unwrap();
        println!("{method} {} {}", res.status(), String::from_utf8(body.to_vec()).unwrap());
    }
}
EOF
